const { paletteEntry, schemaFor } = globalThis.SOAR;

host.replaceChildren();
if (!node) {
  const hint = document.createElement("p");
  hint.className = "muted tiny";
  hint.textContent = "Select a node to edit its inputs, retry policy, error " +
    "branch and compensation. Drag from a port to connect it to the next step.";
  host.append(hint);
  return;
}

const entry = paletteEntry(node, palette);

const heading = document.createElement("h3");
heading.className = "card-title";
heading.textContent = entry?.label || node.kind;
host.append(heading);

if (entry?.doc) {
  const doc = document.createElement("p");
  doc.className = "muted tiny";
  doc.textContent = entry.doc;
  host.append(doc);
}

// A response node explains, per vendor, what this action actually does -
// because "isolate" means five different things across five EDRs.
if (node.kind === "response" && entry?.coverage) {
  host.append(renderCoverage(entry.coverage));
}

host.append(field({
  key: "__label", label: "Step name", type: "string",
  value: node.label || "",
  hint: "What this step is called on the canvas and in the execution console.",
  onChange: (value) => context.update(node.id, (n) => { n.label = value; }),
}));

const schema = schemaFor(node, palette);
const required = new Set(schema?.required || []);
for (const [key, spec] of Object.entries(schema?.properties || {})) {
  host.append(field({
    key,
    label: key.replace(/_/g, " "),
    type: spec.enum ? "enum" : spec.widget || spec.type || "string",
    options: spec.enum || modeOptions(node, entry, key),
    value: node.config?.[key] ?? spec.default ?? "",
    required: required.has(key),
    hint: spec.description || describeSpec(spec),
    variables: context.variables,
    onChange: (value) => context.update(node.id, (n) => {
      n.config = { ...(n.config || {}), [key]: value };
    }),
  }));
}

if (entry?.outputs && Object.keys(entry.outputs).length) {
  host.append(renderOutputs(node, entry, context));
}

host.append(renderReliability(node, entry, context));

if (entry?.effect === "mutating") {
  host.append(renderCompensation(node, entry, palette, context));
}

const wrapper = document.createElement("div");
wrapper.className = "pb-field";
wrapper.dataset.required = String(Boolean(spec.required));

const caption = document.createElement("label");
caption.textContent = spec.label;
caption.htmlFor = `f_${spec.key}`;
wrapper.append(caption);

let control;
if (spec.type === "enum" && (spec.options || []).length) {
  control = document.createElement("select");
  for (const option of ["", ...spec.options]) {
    const item = document.createElement("option");
    item.value = option;
    item.textContent = option || "(not set)";
    control.append(item);
  }
  control.value = String(spec.value ?? "");
} else if (spec.type === "code" || spec.type === "object" || spec.type === "mapping") {
  control = document.createElement("textarea");
  control.spellcheck = false;
  control.value = typeof spec.value === "string"
    ? spec.value
    : JSON.stringify(spec.value ?? {}, null, 2);
} else if (spec.type === "boolean") {
  control = document.createElement("input");
  control.type = "checkbox";
  control.checked = Boolean(spec.value);
} else if (spec.type === "integer" || spec.type === "number") {
  control = document.createElement("input");
  control.type = "number";
  control.value = spec.value ?? "";
} else {
  control = document.createElement("input");
  control.type = "text";
  control.value = spec.value ?? "";
}

control.id = `f_${spec.key}`;
control.addEventListener("change", () => {
  let value = control.type === "checkbox" ? control.checked : control.value;
  if (spec.type === "integer") value = value === "" ? undefined : Number(value);
  if (spec.type === "object" || spec.type === "mapping") {
    try { value = JSON.parse(value || "{}"); }
    catch { control.setCustomValidity("not valid JSON"); return; }
    control.setCustomValidity("");
  }
  spec.onChange(value);
});
wrapper.append(control);

if (spec.variables && spec.type !== "boolean" && spec.type !== "integer") {
  const insert = document.createElement("button");
  insert.type = "button";
  insert.className = "pb-varbtn";
  insert.textContent = "{{ }}";
  insert.title = "Insert a variable";
  insert.addEventListener("click", () => openVariablePicker(spec.variables,
    (path) => {
      control.value = `${control.value}{{ ${path} }}`;
      control.dispatchEvent(new Event("change"));
    }));
  caption.append(insert);
}

if (spec.hint) {
  const hint = document.createElement("div");
  hint.className = "pb-hint";
  hint.textContent = spec.hint;
  wrapper.append(hint);
}
return wrapper;

const parts = [];
if (spec.type === "array") parts.push("a list");
else if (spec.type === "integer") parts.push("a whole number");
else if (spec.type === "object") parts.push("JSON");
else if (spec.type === "string") parts.push("text");
if (spec.format === "email") parts.push("an email address");
if (spec.minLength) parts.push(`at least ${spec.minLength} characters`);
if (spec.maxLength) parts.push(`at most ${spec.maxLength} characters`);
if (spec.minimum !== undefined) parts.push(`minimum ${spec.minimum}`);
if (spec.maximum !== undefined) parts.push(`maximum ${spec.maximum}`);
if (spec.minItems) parts.push(`at least ${spec.minItems} entries`);
if (spec.maxItems) parts.push(`at most ${spec.maxItems} entries`);
if (spec.pattern === "^[0-9a-fA-F]{64}$") parts.push("a SHA-256 hash");
if (spec.pattern === "^[0-9a-fA-F]{40}$") parts.push("a SHA-1 hash");
return parts.join(", ");

if (key !== "mode" || node.kind !== "response") return null;
const modes = new Set();
for (const detail of Object.values(entry?.coverage?.semantics || {})) {
  for (const mode of detail.modes || []) modes.add(mode);
}
return modes.size ? [...modes] : null;

const wrapper = document.createElement("div");
wrapper.className = "pb-section";

const title = document.createElement("span");
title.className = "pb-group-name";
title.textContent = "Estate coverage";
wrapper.append(title);

const headline = document.createElement("p");
headline.className = "mono tiny";
headline.textContent =
  `${coverage.hosts_covered} of ${coverage.hosts_total} hosts ` +
  `(${coverage.percent}%)`;
wrapper.append(headline);

for (const [name, detail] of Object.entries(coverage.semantics || {})) {
  const note = document.createElement("div");
  note.className = "pb-vendor-note";
  const heading = document.createElement("strong");
  heading.textContent = name;
  const body = document.createElement("div");
  body.textContent = detail.semantics || detail.command;
  note.append(heading, body);
  if (detail.expected_seconds) {
    const timing = document.createElement("div");
    timing.className = "muted";
    timing.textContent = `typically ~${detail.expected_seconds}s` +
      (detail.reversible ? " · reversible" : " · NOT reversible");
    note.append(timing);
  }
  wrapper.append(note);
}

for (const spot of coverage.blind_spots || []) {
  const note = document.createElement("div");
  note.className = "pb-problem";
  note.dataset.severity = "warning";
  note.textContent = `${spot.integration}: ${spot.reason}`;
  wrapper.append(note);
}

if (coverage.percent < 99) {
  const advice = document.createElement("div");
  advice.className = "pb-problem";
  advice.dataset.severity = "warning";
  advice.textContent =
    "Wire the on_unsupported branch so hosts this cannot reach get a human " +
    "task instead of a failed step.";
  wrapper.append(advice);
}
return wrapper;

const wrapper = document.createElement("div");
wrapper.className = "pb-section";

const title = document.createElement("span");
title.className = "pb-group-name";
title.textContent = "Output";
wrapper.append(title);

wrapper.append(field({
  key: "output_var", label: "Store result as", type: "string",
  value: node.output_var || "",
  hint: "Later steps read it as {{ <name> }} or {{ steps." + node.id + ".output }}",
  onChange: (value) => context.update(node.id, (n) => { n.output_var = value || undefined; }),
}));

const list = document.createElement("div");
list.className = "pb-hint mono";
list.textContent = "fields: " + Object.keys(entry.outputs).join(", ");
wrapper.append(list);
return wrapper;

const wrapper = document.createElement("div");
wrapper.className = "pb-section";

const title = document.createElement("span");
title.className = "pb-group-name";
title.textContent = "Reliability";
wrapper.append(title);

wrapper.append(field({
  key: "retry_max", label: "Retries", type: "integer",
  value: node.retry?.max ?? 0,
  hint: "Transient and rate-limit errors only. Auth and validation failures " +
        "are never retried.",
  onChange: (value) => context.update(node.id, (n) => {
    n.retry = value ? { max: Number(value), backoff: "exponential" } : undefined;
  }),
}));

wrapper.append(field({
  key: "timeout_ms", label: "Timeout (ms)", type: "integer",
  value: node.timeout_ms ?? entry?.timeout_ms ?? "",
  hint: "Wall clock. The step is killed with its process tree when it expires.",
  onChange: (value) => context.update(node.id, (n) => {
    n.timeout_ms = value ? Number(value) : undefined;
  }),
}));
return wrapper;

const wrapper = document.createElement("div");
wrapper.className = "pb-section";

const title = document.createElement("span");
title.className = "pb-group-name";
title.textContent = "Compensation";
wrapper.append(title);

const options = context.model.nodes
  .filter((n) => n.id !== node.id)
  .map((n) => n.id);

wrapper.append(field({
  key: "compensation", label: "Undo with", type: "enum", options,
  value: node.compensation || "",
  hint: "Run in reverse order if a later step fails. Nothing is rolled back " +
        "unless it is declared here.",
  onChange: (value) => context.update(node.id, (n) => {
    n.compensation = value || undefined;
  }),
}));

if (entry?.undo && !node.compensation) {
  const suggest = document.createElement("button");
  suggest.type = "button";
  suggest.className = "ghost wide";
  suggest.textContent = `Add ${entry.undo} as the compensation`;
  suggest.addEventListener("click", () => context.addCompensation(node.id, entry.undo));
  wrapper.append(suggest);
}
return wrapper;

document.querySelector(".pb-varpicker")?.remove();

const dialog = document.createElement("dialog");
dialog.className = "pb-varpicker card";

const heading = document.createElement("h3");
heading.className = "card-title";
heading.textContent = "Insert a variable";
dialog.append(heading);

for (const root of variables || []) {
  const group = document.createElement("div");
  group.className = "pb-section";

  const name = document.createElement("span");
  name.className = "pb-group-name";
  name.textContent = `${root.root} — ${root.doc}`;
  group.append(name);

  const paths = root.fields.length
    ? root.fields.map((f) => `${root.root}.${f}`)
    : [root.root];
  for (const path of paths) {
    const option = document.createElement("button");
    option.type = "button";
    option.className = "pb-item";
    option.textContent = path;
    option.addEventListener("click", () => { onPick(path); dialog.close(); dialog.remove(); });
    group.append(option);
  }
  dialog.append(group);
}

const close = document.createElement("button");
close.type = "button";
close.className = "ghost wide";
close.textContent = "Cancel";
close.addEventListener("click", () => { dialog.close(); dialog.remove(); });
dialog.append(close);

document.body.append(dialog);
dialog.showModal();

globalThis.SOAR = globalThis.SOAR || {};
Object.assign(globalThis.SOAR, {
  renderInspector,
  field,
  openVariablePicker,
});
